			&OutlineEntry;
			&JavascriptReportFilter; 

function active$VoucherFilter$(f) {
	f.add_onResponseComplete(on$Filter$ResponseComplete); 
	if (!f.getItemValue('year')) {
		var y = (new Date()).getFullYear();
		f.setItemValues('year', [y]);
	}
}
function close$VoucherFilter$(f) {
	try {f.remove_onResponseComplete(on$Filter$ResponseComplete);} catch (ex) {}
}
function onChange$Month(o) {
	var f = o.parentForm;
	var thang = f.getItemValue('month');
	f.setItemValues('month_from, month_to', [thang, thang]);
}
function on$Filter$ResponseComplete(sender, e) {
	var f = e.object, context = e.type.Context, result = e.type.Result;
	switch (context) {
		case 'Checking':
			var g = f.grid; 
			g._hiddenForms = [];
			var thang = f.getItemValue('month');
			var nam = f.getItemValue('year');
			g._alterTitle = [null, [['%s1', thang, true], ['%s2', nam, true]]];
			//remove$GridReport$Filter(g);
			break;
		default:
			break;
	}
}




